; >S:SCATTER; PUT "SCATTER";; THE MEGA CODE TO SCATTER THE; JIGSAW PIECES INTO THE ROOMS; AND DISPLAY THE ROOMS QUICKLY; AND THE PIECES DISAPPEARING.;SCATER;JSR PRJIG;; PRINT COMPLETE JIGSAW;LDA #1STA DELLY  ;* DELAY;LDA #0STA SCREEN ;* 0-24;SCAT1;JSR RADAR  ;* DISPLAY POS;JSR DECODE ;* SCREEN DECRUNCHJSR FADEIN ;* PUT IT ON;JSR PRPICE ;* PRINT JIGSAW PIECE;LDX #$40JSR DELAY+2;JSR GETRID ;* GET RID OF THAT;JSR COLJIG;BIT JFIREBMI HUNCK;; FIRE TO ESCAPE;LDX #$10JSR DELAY+2;INC SCREENLDA SCREENCMP #25BNE SCAT1;RTS;HUNCK;; CARRY ON WITH NO TIME DELAY;NOPAL;JSR RADARJSR GETRID;LDX #$20JSR DELAY+2;JSR COLJIG;INC SCREENLDA SCREENCMP #25BNE NOPAL;RTS;;--------------------------------;GETRID;LDX SCREENLDA JIGNUM,XCLCADC #215STA COPY;LDX #24;SCAT2;LDY RADY,XLDA $E02,Y;CMP COPYBNE NTSCAT;LDA #27STA $E02,Y;NTSCAT;DEXBPL SCAT2;; JSR COLJIG;RTS;;;;.END